import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { MapPin, Phone, Mail, Clock, Check } from 'lucide-react';

const Contact: React.FC = () => {
  const location = useLocation();
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    message: ''
  });
  const [isSubmitted, setIsSubmitted] = useState(false);

  useEffect(() => {
    if (location.state) {
      const { message } = location.state as { message?: string };
      if (message) {
        setFormData(prev => ({ ...prev, message }));
      }
    }
  }, [location.state]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Simulate API call
    setIsSubmitted(true);
    // Reset form after delay or keep success state
    setTimeout(() => setIsSubmitted(false), 5000);
    setFormData({ firstName: '', lastName: '', email: '', phone: '', message: '' });
    alert("Thank you for your inquiry. One of our agents will contact you shortly.");
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  return (
    <div className="pt-20 min-h-screen bg-nexora-offWhite">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-16">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-16">

          {/* Contact Info */}
          <div>
            <h1 className="text-4xl font-serif font-bold text-nexora-black mb-6">Get in Touch</h1>
            <p className="text-gray-600 mb-12 text-lg">
              Whether you're looking to buy, sell, or just want to discuss the market, our team is ready to assist you.
            </p>

            <div className="space-y-8">
              <div className="flex items-start">
                <div className="w-12 h-12 bg-nexora-beige/20 rounded-full flex items-center justify-center text-nexora-black shrink-0 mr-6">
                  <MapPin size={24} />
                </div>
                <div>
                  <h3 className="font-bold text-lg text-nexora-black mb-1">Visit Us</h3>
                  <p className="text-gray-500">Level 42, The Opus<br/>Business Bay, Dubai, UAE</p>
                </div>
              </div>

              <div className="flex items-start">
                <div className="w-12 h-12 bg-nexora-beige/20 rounded-full flex items-center justify-center text-nexora-black shrink-0 mr-6">
                  <Phone size={24} />
                </div>
                <div>
                  <h3 className="font-bold text-lg text-nexora-black mb-1">Call Us</h3>
                  <p className="text-gray-500">+971 4 123 4567</p>
                  <p className="text-gray-400 text-sm">Mon-Fri from 9am to 6pm</p>
                </div>
              </div>

               <div className="flex items-start">
                <div className="w-12 h-12 bg-nexora-beige/20 rounded-full flex items-center justify-center text-nexora-black shrink-0 mr-6">
                  <Mail size={24} />
                </div>
                <div>
                  <h3 className="font-bold text-lg text-nexora-black mb-1">Email Us</h3>
                  <p className="text-gray-500">concierge@nexora.realty</p>
                </div>
              </div>
            </div>
          </div>

          {/* Form */}
          <div className="bg-white p-8 md:p-10 rounded-2xl shadow-lg">
            <h2 className="text-2xl font-bold mb-6 font-serif">Send a Message</h2>

            {isSubmitted ? (
              <div className="bg-green-50 border border-green-100 rounded-lg p-6 text-center animate-fade-in-up">
                 <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4 text-green-600">
                    <Check size={32} />
