                <button type="submit" className="w-full py-4 bg-nexora-black text-white font-bold uppercase tracking-widest rounded-lg hover:bg-nexora-teal transition-all duration-300">
                  Submit Inquiry
                </button>
              </form>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Contact;

import React, { useState, useMemo, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Filter, SlidersHorizontal, X } from 'lucide-react';
import PropertyCard from '../components/PropertyCard';
import { PROPERTIES } from '../constants';

const Listings: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const queryParams = new URLSearchParams(location.search);

  const [locationFilter, setLocationFilter] = useState('All');
  const [typeFilter, setTypeFilter] = useState('All');
  const [priceRange, setPriceRange] = useState<[number, number]>([0, 50000000]);

  // Sync state with URL params on mount or url change
  useEffect(() => {
    const loc = queryParams.get('location');
    const type = queryParams.get('type');
    if (loc) setLocationFilter(loc);
    if (type) setTypeFilter(type);
  }, [location.search]);

  const filteredProperties = useMemo(() => {
    return PROPERTIES.filter(p => {
      const matchLoc = locationFilter === 'All' || p.location.includes(locationFilter);
      const matchType = typeFilter === 'All' || p.type === typeFilter;
      const matchPrice = p.price >= priceRange[0] && p.price <= priceRange[1];
      return matchLoc && matchType && matchPrice;
    });
  }, [locationFilter, typeFilter, priceRange]);

  const locations = ['All', ...Array.from(new Set(PROPERTIES.map(p => p.location.split(',')[0])))];
  const types = ['All', ...Array.from(new Set(PROPERTIES.map(p => p.type)))];

  const handleClearFilters = () => {
    setLocationFilter('All');
    setTypeFilter('All');
    navigate('/listings');
  };

  return (
    <div className="pt-20 min-h-screen bg-nexora-offWhite">
      {/* Header */}
      <div className="bg-nexora-black text-white py-16 px-4">
        <div className="max-w-7xl mx-auto text-center">
          <h1 className="text-4xl md:text-5xl font-serif font-bold mb-4">Curated Collection</h1>
          <p className="text-gray-400 max-w-2xl mx-auto">Explore our portfolio of exclusive properties across the region's most prestigious addresses.</p>
        </div>
      </div>

      {/* Filter Bar (Sticky) */}
      <div className="sticky top-20 z-30 bg-white shadow-md border-b border-gray-100">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
          <div className="flex flex-col md:flex-row justify-between items-center gap-4">

            <div className="flex items-center gap-2 w-full md:w-auto overflow-x-auto hide-scrollbar pb-2 md:pb-0">
               <span className="text-nexora-black font-semibold flex items-center mr-2"><Filter size={16} className="mr-1"/> Filter:</span>

               <select 
                value={locationFilter}
                onChange={(e) => setLocationFilter(e.target.value)}
                className="bg-gray-100 text-sm rounded-full px-4 py-2 border-none focus:ring-2 focus:ring-nexora-beige cursor-pointer outline-none"
               >
                 {locations.map(l => <option key={l} value={l}>{l === 'All' ? 'All Locations' : l}</option>)}
               </select>

               <select 
                value={typeFilter}
                onChange={(e) => setTypeFilter(e.target.value)}
                className="bg-gray-100 text-sm rounded-full px-4 py-2 border-none focus:ring-2 focus:ring-nexora-beige cursor-pointer outline-none"
               >
                 {types.map(t => <option key={t} value={t}>{t === 'All' ? 'All Types' : t}</option>)}
               </select>

               {(locationFilter !== 'All' || typeFilter !== 'All') && (
                 <button 
                   onClick={handleClearFilters}
                   className="flex items-center text-xs font-bold text-red-500 hover:text-red-700 transition-colors ml-2"
                 >
                   <X size={14} className="mr-1" /> Clear
                 </button>
               )}
            </div>

            <div className="text-sm text-gray-500 font-medium">
              Showing {filteredProperties.length} Properties
            </div>
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        {filteredProperties.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {filteredProperties.map(property => (
              <PropertyCard key={property.id} property={property} />
            ))}
          </div>
        ) : (
          <div className="text-center py-24">
            <div className="bg-gray-200 rounded-full w-20 h-20 flex items-center justify-center mx-auto mb-4">
               <SlidersHorizontal className="text-gray-400" size={32} />
            </div>
            <h3 className="text-xl font-bold text-gray-800">No Properties Found</h3>
            <p className="text-gray-500 mt-2">Try adjusting your filters to see more results.</p>
            <button 
              onClick={handleClearFilters}
              className="mt-6 px-6 py-2 bg-nexora-beige text-nexora-black font-semibold rounded-lg hover:bg-nexora-teal hover:text-white transition-colors"
            >
              Clear Filters
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default Listings;

import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Menu, X, Phone } from 'lucide-react';

const Navbar: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const location = useLocation();

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Close mobile menu on route change
  useEffect(() => {
    setIsMobileMenuOpen(false);
  }, [location]);

  const navBackground = isScrolled || location.pathname !== '/' 
    ? 'bg-nexora-black/95 backdrop-blur-md border-b border-white/10' 
    : 'bg-transparent';

  const textColor = isScrolled || location.pathname !== '/' ? 'text-nexora-offWhite' : 'text-nexora-black';

  return (
    <nav className={`fixed w-full z-50 transition-all duration-300 ${navBackground}`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-20">
          {/* Logo */}
          <Link to="/" className="flex items-center space-x-2 group">
            <div className="w-8 h-8 bg-nexora-beige rounded-sm rotate-45 group-hover:rotate-0 transition-transform duration-500"></div>
            <span className={`text-2xl font-serif font-bold tracking-wide ${isScrolled || location.pathname !== '/' ? 'text-white' : 'text-nexora-black'}`}>
              NEXORA
            </span>
          </Link>

          {/* Desktop Links */}
          <div className="hidden md:flex items-center space-x-8">
            <Link to="/" className={`text-sm uppercase tracking-widest hover:text-nexora-beige transition-colors ${isScrolled || location.pathname !== '/' ? 'text-gray-300' : 'text-gray-800'}`}>Home</Link>
            <Link to="/listings" className={`text-sm uppercase tracking-widest hover:text-nexora-beige transition-colors ${isScrolled || location.pathname !== '/' ? 'text-gray-300' : 'text-gray-800'}`}>Listings</Link>
            <Link to="/agents" className={`text-sm uppercase tracking-widest hover:text-nexora-beige transition-colors ${isScrolled || location.pathname !== '/' ? 'text-gray-300' : 'text-gray-800'}`}>Agents</Link>

            <Link to="/contact" className="px-6 py-2 bg-nexora-beige text-nexora-black font-semibold text-sm uppercase tracking-wider hover:bg-nexora-teal hover:text-white transition-all duration-300">
              Book Viewing
            </Link>
          </div>

          {/* Mobile Menu Button */}
          <div className="md:hidden flex items-center">
            <button 
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
              className={`${isScrolled || location.pathname !== '/' ? 'text-white' : 'text-nexora-black'} hover:text-nexora-beige`}
            >
              {isMobileMenuOpen ? <X size={28} /> : <Menu size={28} />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      <div className={`md:hidden fixed inset-0 bg-nexora-black z-40 transform ${isMobileMenuOpen ? 'translate-x-0' : 'translate-x-full'} transition-transform duration-300 pt-24 px-6`}>
         <div className="flex flex-col space-y-8">
            <Link to="/" className="text-2xl font-serif text-white hover:text-nexora-beige">Home</Link>
            <Link to="/listings" className="text-2xl font-serif text-white hover:text-nexora-beige">Properties</Link>
            <Link to="/agents" className="text-2xl font-serif text-white hover:text-nexora-beige">Agents</Link>
            <Link to="/contact" className="text-2xl font-serif text-white hover:text-nexora-beige">Contact</Link>

            <div className="pt-8 border-t border-white/10">
              <a href="tel:+971500000000" className="flex items-center text-nexora-teal text-lg">
                <Phone className="mr-3" size={20} />
                +971 50 000 0000
              </a>
            </div>
         </div>
      </div>
    </nav>
  );
};

export default Navbar;

